+//! Hosted editing: one host owns the user history; engine history is transaction-local.
+//! This is deliberately restricted to the host's allowlisted, document-local commands.
+use crate::{DocState, EngineError, Result, Session, ToolState};
+use photocraft_doc::{Document, LayerId};
+use photocraft_ops::{History, LayerTarget};
+use serde_json::Value;
+use std::sync::Arc;
+
+pub struct Checkpoint {
+    state: DocState,
+    tools: ToolState,
+    clipboard: Option<crate::edit_cmds::Clip>,
+    journal: Vec<(String, Value)>,
+    typed_layer: Option<(photocraft_doc::DocId, LayerId)>,
+}
+impl Session {
+    /// Capture before dispatch (not after precheck): dispatch may drop a floating selection before
+    /// admission. The allowlist must exclude file, plugin, action, profile and document lifecycle commands.
+    pub fn host_checkpoint(&self) -> Result<Checkpoint> {
+        if self.active_job().is_some() {
+            return Err(EngineError::Other("host transaction has an active job".into()));
+        }
+        Ok(Checkpoint {
+            state: self.active().ok_or(EngineError::NoDocument)?.clone(),
+            tools: self.tools.clone(),
+            clipboard: self.clipboard.clone(),
+            journal: self.journal.clone(),
+            typed_layer: self.typed_layer,
+        })
+    }
+    pub fn host_restore(&mut self, checkpoint: Checkpoint) -> Result<()> {
+        if self.active_job().is_some() {
+            return Err(EngineError::Other("cannot restore with an active job".into()));
+        }
+        let st = self.active_mut().ok_or(EngineError::NoDocument)?;
+        if st.doc.id != checkpoint.state.doc.id {
+            return Err(EngineError::Other("host checkpoint document mismatch".into()));
+        }
+        let revision = st.revision.checked_add(1).ok_or_else(|| EngineError::Other("revision exhausted".into()))?;
+        let clean = !checkpoint.state.is_dirty();
+        *st = checkpoint.state;
+        st.revision = revision;
+        if clean {
+            st.saved_revision = revision;
+        }
+        // Floating pieces are revision-bound. A rollback restores that same source document,
+        // under the new monotonic revision, so its continuation must move with the revision.
+        if let Some(floating) = &mut st.floating {
+            floating.revision = revision;
+        }
+        st.last_damage = None;
+        self.tools = checkpoint.tools;
+        self.clipboard = checkpoint.clipboard;
+        self.journal = checkpoint.journal;
+        self.typed_layer = checkpoint.typed_layer;
+        self.host_invalidate();
+        Ok(())
+    }
+    /// Install exactly the host's immutable document and target. Does not synthesize Undo/Redo.
+    /// The host must settle gestures before calling this. File identity remains host-owned.
+    pub fn host_install(&mut self, document: Arc<Document>, target: LayerTarget) -> Result<()> {
+        if self.active_job().is_some() {
+            return Err(EngineError::Other("cannot install with an active job".into()));
+        }
+        let st = self.active_mut().ok_or(EngineError::NoDocument)?;
+        if st.floating.is_some() {
+            return Err(EngineError::Other("settle the floating selection before install".into()));
+        }
+        if st.doc.id != document.id {
+            return Err(EngineError::Other("host version document mismatch".into()));
+        }
+        document.scratch_health().map_err(EngineError::Other)?;
+        let revision = st.revision.checked_add(1).ok_or_else(|| EngineError::Other("revision exhausted".into()))?;
+        st.doc = document;
+        st.revision = revision;
+        st.coalesce = None;
+        st.show_only = None;
+        st.last_damage = None;
+        crate::session::restore_target(st, target);
+        self.host_clear_history()?;
+        self.host_invalidate();
+        Ok(())
+    }
+    /// Release transaction-local history only once the host has retained the candidate version.
+    /// No persistent data is removed. Host-pinned Arc documents are unaffected.
+    pub fn host_clear_history(&mut self) -> Result<()> {
+        let st = self.active_mut().ok_or(EngineError::NoDocument)?;
+        let target = LayerTarget { active: st.active_layer, selected: st.selected_layers.clone() };
+        st.history = History::new(1);
+        st.history.set_current_layers(target);
+        st.snapshots.clear();
+        st.source_snapshot = None;
+        st.coalesce = None;
+        self.journal.clear();
+        self.typed_layer = None;
+        Ok(())
+    }
+    fn host_invalidate(&mut self) {
+        self.live_commit = None;
+        self.subject_cache = Default::default();
+        self.object_finder = Default::default();
+        self.coalesce_request = None;
+        self.color_restrict = None;
+        self.filter_mask_layer = None;
+        self.sampler_map = None;
+        self.symmetry_map = None;
+        photocraft_compose::discard_unreadable_pixel_caches();
+    }
+}

