+/// Host-owned append-only storage. Existing objects are verified, never repaired or removed.
+/// Object publication must be exclusive; finish flushes the object namespace before a manifest may publish.
+/// Partial writes are retained by the host.
+pub enum SnapshotObject { Missing, Bytes(Vec<u8>), Verified }
+pub trait SnapshotSink {
+    /// Verified may only be returned for an object previously verified/published through this
+    /// sink and whose strong file identity/signature is unchanged under the exclusive host lease.
+    fn get(&mut self, path: &str, max: usize) -> Result<SnapshotObject>;
+    fn verified(&mut self, path: &str) -> Result<()>;
+    fn publish(&mut self, path: &str, compressed: &[u8]) -> Result<()>;
+    fn finish(&mut self) -> Result<()>;
+}

 pub trait ByteSource {
     fn get(&self, path: &str, max: usize) -> Result<Vec<u8>>;
