+    /// Prepare an immutable native snapshot in host-owned append-only storage. Only missing
+    /// objects are compressed and published. Existing content is decoded and verified; corruption
+    /// fails without replacing evidence. No manifest, GC, recovery lifecycle or paths are owned here.
+    /// The host must publish the returned manifest only after all objects are durable.
+    pub fn append_snapshot(&mut self, doc: &Document, sink: &mut impl SnapshotSink) -> Result<Vec<u8>> {
+        let generation = photocraft_raster::spill::read_error_generation();
+        let p = self.prepare(doc, &SaveOptions::default())?;
+        let mut compressor = None;
+        for (path, obj) in &p.objects {
+            let content = obj.content();
+            let max = content.len().saturating_mul(2).saturating_add(1 << 20);
+            match sink.get(path, max)? {
+                SnapshotObject::Verified => {},
+                SnapshotObject::Bytes(bytes) if content_matches(&content, &bytes, path) => sink.verified(path)?,
+                SnapshotObject::Bytes(_) => return Err(FormatError::Corrupt(format!("immutable object is corrupt: {path}"))),
+                SnapshotObject::Missing => {
+                    let bytes = obj.compressed(compressor.get_or_insert_with(Compressor::new));
+                    sink.publish(path, &bytes)?;
+                }
+            }
+        }
+        sink.finish()?;
+        scratch_ok(doc, generation)?;
+        Ok(p.manifest)
     }

